  const score = card => (card.pos === 'curado' ? 100 : 0) +
    (card.cefr === 'A1' ? 12 : card.cefr === 'A2' ? 8 : card.cefr === 'B1' ? 4 : 0) +
    (card.phrase?.text ? 2 : 0) + (card.zipf || 0) / 100;

  function apply(source) {
    if (!Array.isArray(source)) throw new TypeError('Catálogo deve ser um array.');
    const overrides = new Map(entries.map(([word, meanings, pos, text, translation]) => [word, {
      meaning: meanings.split('|'), pos, definition: '',
      phrase: { text, translation, source: 'Exemplo original do Voca Sprint' },
      curated: true
    }]));
    const preferred = new Map();
    for (const card of source) {
      if (!card || typeof card.word !== 'string' || !card.meaning?.length || !overrides.has(card.word)) continue;
      const old = preferred.get(card.word);
      if (!old || score(card) > score(old)) preferred.set(card.word, card);
    }
    const out = source.map(card => {
      const original = preferred.get(card.word);
      const patch = overrides.get(card.word);
      if (!original || !patch || card.id !== original.id) return card;
      // Os demais metadados e o identificador permanecem iguais.
      return { ...card, ...patch, ...(card.word === 'want' ? { cefr: 'A1' } : {}) };
    });
    for (const [word, patch] of overrides) {
      if (preferred.has(word)) continue;
      out.push({ id: `${word}:1`, senseIndex: 0, word, rank: 0, cefr: 'A1', zipf: 0, ...patch });
    }
    return out;
  }

  window.VocaCuratedCards = Object.freeze({ apply, count: entries.length, version: '1.0' });
